<?php

$redis = new Redis();
$redis->connect("127.0.0.1");
// $redis->connect("127.0.0.1", 2002);

$data1k  = ">";
$data4k  = $data1k . $data1k . $data1k . $data1k;
$data16k = $data4k . $data4k . $data4k . $data4k;

$redis->del("a");

while($redis->strlen("a") < 5 * 1024 * 1024 - 0 * 1024)
	$redis->append("a", $data16k);

echo $redis->strlen("a") . "\n";

